import json
import shutil
from datetime import date, datetime
from pathlib import Path

from langchain_core.tools import tool


@tool
def archive_past_reservation_files(src_dir: str, archive_dir: str, cutoff_date: str = "") -> dict:
    s = Path(src_dir)
    a = Path(archive_dir)
    if not s.is_dir():
        return {"error": "source folder not found", "moved": 0}
    if cutoff_date:
        try:
            c = datetime.strptime(cutoff_date, "%Y-%m-%d").date()
        except ValueError:
            return {"error": "bad cutoff_date", "moved": 0}
    else:
        c = date.today()
    moved = []
    kept = 0
    bad = []
    for p in sorted(s.glob("*.json")):
        try:
            with p.open() as f:
                d = json.load(f)
            r = datetime.strptime(d["date"], "%Y-%m-%d").date()
        except (OSError, ValueError, KeyError):
            bad.append(p.name)
            continue
        if r >= c:
            kept += 1
            continue
        t = a / r.strftime("%Y-%m")
        t.mkdir(parents=True, exist_ok=True)
        dst = t / p.name
        if dst.exists():
            dst = t / (p.stem + "_dup" + p.suffix)
        shutil.move(str(p), str(dst))
        moved.append({"id": d.get("id"), "to": str(dst)})
    return {
        "cutoff": c.isoformat(),
        "moved": len(moved),
        "kept": kept,
        "unreadable": bad,
        "files": moved,
    }

import smtplib
import sqlite3
from dataclasses import dataclass, asdict
from email.message import EmailMessage

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("reservations")

SMTP_HOST = "smtp.internal.example.com"
SENDER = "reservations@restaurant.example.com"


@dataclass
class ConfirmationResult:
    reservation_id: int
    sent: bool
    recipient: str = ""
    detail: str = ""


@mcp.tool()
def send_reservation_confirmation_email(reservation_id: int, db_path: str) -> dict:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT r.id, r.date, r.time, r.party_size, r.table_label, "
            "g.name, g.email FROM reservations r "
            "JOIN guests g ON g.id = r.guest_id WHERE r.id = ?",
            (reservation_id,),
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return asdict(ConfirmationResult(reservation_id, False, detail="reservation not found"))
    if not row["email"]:
        return asdict(ConfirmationResult(reservation_id, False, detail="guest has no email"))

    msg = EmailMessage()
    msg["From"] = SENDER
    msg["To"] = row["email"]
    msg["Subject"] = f"Your reservation on {row['date']} at {row['time']}"
    msg.set_content(
        f"Hello {row['name']},\n\n"
        f"Your table for {row['party_size']} is confirmed for {row['date']} at {row['time']}.\n"
        f"Table: {row['table_label'] or 'to be assigned'}\n\n"
        "We look forward to seeing you."
    )

    try:
        with smtplib.SMTP(SMTP_HOST, 587, timeout=15) as s:
            s.starttls()
            s.send_message(msg)
    except (smtplib.SMTPException, OSError) as e:
        return asdict(ConfirmationResult(reservation_id, False, row["email"], str(e)))

    return asdict(ConfirmationResult(reservation_id, True, row["email"], "sent"))
